const menuButton=document.querySelector('.menu-toggle');const nav=document.querySelector('#site-nav');menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')==='true';menuButton.setAttribute('aria-expanded',String(!open));nav.classList.toggle('open',!open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false')}));
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
document.querySelector('#quote-form').addEventListener('submit',async e=>{e.preventDefault();const data=new FormData(e.currentTarget);const message=`Olá, Oficina Dois! Meu nome é ${data.get('nome')}.\n\nPreciso de: ${data.get('servico')}\nUso principal: ${data.get('uso')}\nWhatsApp: ${data.get('whatsapp')||'prefiro falar pelo Direct'}\nDetalhes: ${data.get('detalhes')||'podemos conversar sobre a configuração.'}`;const status=e.currentTarget.querySelector('.form-status');try{await navigator.clipboard.writeText(message);status.textContent='Pedido copiado! Abrindo o Instagram — é só colar no Direct.'}catch{status.textContent='Abrindo o Instagram para você enviar seu pedido pelo Direct.'}setTimeout(()=>window.open('https://www.instagram.com/oficinandois.pc/','_blank','noopener'),350)});
